.list-wrapper{
	.item{
		display flex
		align-items center
		justify-content space-between
		background-color #fff
		padding: 8px;
		margin-bottom: 10px;
		&:nth-last-child(1){
			margin-bottom 0!important
		}
		.info{
			display flex
			flex-direction column
			justify-content space-between
			margin-left: 10px;
			flex: 1;
			.titleCon{
				height: 52px;
			}
			.title{
				color #333
				font-size 14px
			}
			.bottom{
				color: #999999;
				font-size 12px;
				.right{
					display: flex;
					align-items: center;
					.iconfont{
						font-size: 16px;
						margin-right: 4px;
					}
					.like{
						margin-left: 16px;
						.likeNum{
							padding-top: 2px;
						}
					}
				}
			}
		}
		.empty-box{
			width:120px;
			height:76px;
			background: #F3F9FF
			img {
				width: 50px !important;
				height: 38px !important;
			}
		}
		.pictrue{
			width 120px;
			height 76px;
			img{
				width 100%;
				height 100%;
				object-fit: cover;
			}
		}
